import {resolveLocale,setLocale,t,installPageTranslation,locale} from './i18n.mjs';
import {localizeModel} from './locale-model.mjs';
import {landscape,preparationMarkup,emailDraft} from './experience.mjs';
import {VERSION,traits,questions,agreement,scoreAnswers,band,profileFor,validDraft} from './model.mjs';
import {categoryInsight,selectedActions,planProgress} from './report.mjs';
import {leanGroups,historySeries,wedgePath} from './charts.mjs';
import {assessmentStatus} from './navigation.mjs';
import {growthState,companionMarkup} from './companion.mjs';
import {journeyState,journeyTrailMarkup} from './journey.mjs';
let preferredLanguage='';try{preferredLanguage=localStorage.getItem('innerly-language')||''}catch{}
setLocale(resolveLocale({url:location.href,saved:preferredLanguage,languages:navigator.languages||[navigator.language]}));localizeModel(locale);document.documentElement.lang=locale;document.title=locale==='hi'?'Innerly — खुद को जानें, अपनी गति से':'Innerly — Understand yourself, at your own pace';
const $=s=>document.querySelector(s),app=$('#app'),storageKey='innerly-personality-v2';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db={reports:[],draft:null,large:false,motionPaused:false},storageAvailable=true,view='home',currentReport=null,index=0,answers=Array(45).fill(null),hasUnsavedAnswers=false,advanceTimer=null,selectedCategory=0;
try{const value=JSON.parse(localStorage.getItem(storageKey));if(value){db.reports=Array.isArray(value.reports)?value.reports.filter(r=>r.version===VERSION&&typeof r.id==='string'&&Array.isArray(r.scores)&&r.scores.length===5&&r.scores.every(s=>Number.isInteger(s)&&s>=0&&s<=100)&&!Number.isNaN(Date.parse(r.date))):[];db.draft=validDraft(value.draft)?value.draft:null;db.large=value.large===true;db.motionPaused=value.motionPaused===true}}catch{storageAvailable=false}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(db));storageAvailable=true;hasUnsavedAnswers=false;return true}catch{storageAvailable=false;hasUnsavedAnswers=true;return false}}
function toast(message){$('#toast').textContent=t(message);$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function setText(large,announce=true){db.large=large;document.documentElement.classList.toggle('large-text',large);$('#regular-type').setAttribute('aria-pressed',String(!large));$('#large-type').setAttribute('aria-pressed',String(large));save();if(view==='quiz')reserveQuestionSpace();if(announce)toast(large?'Larger text is on.':'Comfortable text is on.')}
function focusTitle(){const title=app.querySelector('h1');if(title){title.setAttribute('tabindex','-1');title.focus({preventScroll:true})}window.scrollTo({top:0,behavior:'instant'})}
function cancelAdvance(){clearTimeout(advanceTimer);advanceTimer=null;}
function setView(name){cancelAdvance();view=name;document.body.classList.toggle('taking-test',name==='quiz');$('#home-nav').setAttribute('aria-current',name==='home'?'page':'false');$('#reports-nav').setAttribute('aria-current',name==='history'?'page':'false')}
function bindActions(){app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;if(action==='start')start(false);if(action==='resume')start(true);if(action==='home')home();if(action==='full')openFullReport();if(action==='print')window.print();if(action==='share')shareReport();if(action==='history')history();if(action==='email')saveReportScreen(currentReport);if(action==='new')confirmStartOver();});app.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const r=db.reports.find(r=>r.id===b.dataset.report);if(r)result(r)});}
function home(focus=true){setView('home');const draft=db.draft,done=draft?draft.answers.filter(a=>a!==null).length:0;app.innerHTML=`<section class="discovery-home"><div class="discovery-copy"><div class="eyebrow">SELF-DISCOVERY, AT YOUR PACE</div><h1>A little closer to yourself.</h1><p>Discover how you think, connect, and respond to everyday life.</p><div class="test-facts"><span>45 questions</span><span>8–12 minutes</span></div>${draft?`<p class="resume-note">${done} of 45 answered. Continue where you left off.</p><button class="primary" data-action="resume">Continue test <span aria-hidden="true">→</span></button><button class="text-button" data-action="new">Start again</button>`:`<button class="primary" data-action="start">Start test <span aria-hidden="true">→</span></button>`}<p class="support-note">Get your personality graphs and report. Free for now.</p></div>${landscape}</section><section class="discovery-benefits" aria-label="What you will discover"><article><span aria-hidden="true">◉</span><h2>Understand yourself</h2><p>Notice your everyday preferences.</p></article><article><span aria-hidden="true">♧</span><h2>Connect with others</h2><p>See how you communicate and cooperate.</p></article><article><span aria-hidden="true">↗</span><h2>Find your next step</h2><p>Turn your insights into small actions.</p></article></section><p class="home-reassurance">Your pace. No right or wrong answers.</p><p class="honest-note">For self-reflection. Not a clinical assessment.</p>`;bindActions();if(focus)focusTitle()}

function confirmStartOver(){if(!db.draft){start(false);return}showDialog('Start a fresh assessment?',`<p>This will replace the ${db.draft.answers.filter(a=>a!==null).length} answers in your unfinished assessment. Your completed reports will stay saved.</p><div class="dialog-actions"><button class="secondary" data-dialog-close>Keep my place</button><button class="primary" id="restart-confirm">Start again</button></div>`);$('#restart-confirm').onclick=()=>{$('#info').close();start(false)}}
function start(resume){if(resume&&validDraft(db.draft)){answers=[...db.draft.answers];index=db.draft.index}else{answers=Array(45).fill(null);index=0;db.draft={version:VERSION,answers:[...answers],index};save()}quiz()}
function persistDraft(){db.draft={version:VERSION,answers:[...answers],index};return save()}
let questionLayoutKey='';
function quiz(){
 const reuse=view==='quiz'&&!!app.querySelector('.quiz-shell');
 setView('quiz');
 if(!reuse){
  questionLayoutKey='';
  app.innerHTML=`<div class="quiz-shell"><div class="quiz-toolbar"><span>Question <strong id="question-number"></strong> of 45</span><button class="text-button" id="pause">Save & take a break</button></div><div class="progress-track" role="progressbar" aria-label="Assessment completed" aria-valuemin="0" aria-valuemax="45"><div></div></div><div class="quiz-shortcuts"><button class="text-button" id="question-picker">Questions <span id="answered-count"></span> ▾</button><button class="text-button" id="jump-last">Last question →</button><button class="primary" id="ready-results" hidden>Go to results →</button></div>${companionMarkup()}<section class="question-card"><div class="question-prompt"><div class="scene" hidden><p></p></div><h1 id="question-title" tabindex="-1"></h1><p class="question-help" id="answer-help">Select to move on, or use the arrows.</p></div><p class="sr-only" id="keyboard-help">Choosing an answer moves to the next question automatically. You can also use number keys 1 to 5. Use Previous and Next to browse without changing your answer.</p><fieldset class="answers" aria-describedby="answer-help keyboard-help"><legend class="sr-only" id="answer-legend"></legend>${agreement.map((_,i)=>`<label class="answer" data-choice="${i}"><input type="radio" name="response" value="${i}"><span class="answer-label"></span></label>`).join('')}</fieldset><div class="quiz-actions"><button class="secondary" id="previous"><span aria-hidden="true">←</span> Previous</button><button class="primary" id="next"><span id="next-label">Next</span><span aria-hidden="true">→</span></button></div></section><p class="save-status" id="save-status"></p></div>`;
  app.querySelectorAll('input[name="response"]').forEach(input=>{input.onchange=()=>{const value=Number(input.value);if(answers[index]!==value)selectAnswer(value,true)};input.onclick=()=>selectAnswer(Number(input.value),true);input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selectAnswer(Number(input.value),true)}}});
  mountJourney();
  $('#motion-toggle').onclick=()=>{db.motionPaused=!db.motionPaused;save();updateCompanion()};
  $('#question-picker').onclick=openQuestionPicker;
  $('#jump-last').onclick=()=>jumpToQuestion(questions.length-1);
  $('#ready-results').onclick=finish;
  $('#previous').onclick=()=>moveQuestion(-1);
  $('#next').onclick=()=>{cancelAdvance();if(index===questions.length-1)finish();else moveQuestion(1)};
  $('#pause').onclick=()=>{cancelAdvance();if(persistDraft()){home();toast('Your place is saved. Come back whenever you are ready.')}else showDialog('Keep this tab open',`<p>This browser could not save your progress. Your answers are still here, but closing or refreshing the tab may lose them.</p><button class="primary" data-dialog-close>Continue assessment</button>`)};
 }
 const q=questions[index],answered=answers.filter(a=>a!==null).length;
 $('#question-number').textContent=index+1;
 updateQuizShortcuts();
 $('.progress-track').setAttribute('aria-valuenow',answered);
 $('.progress-track>div').style.width=`${answered/45*100}%`;
 $('#question-title').textContent=q.text;
 $('.question-prompt .scene').hidden=!q.scene;
 $('.question-prompt .scene p').textContent=q.scene||'';
 $('.answers').className=`answers ${q.options?'situation-answers':'agreement-answers'}`;
 $('#answer-legend').textContent=q.options?'Your usual response':'How much you agree';
 app.querySelectorAll('.answer').forEach((label,i)=>{label.querySelector('.answer-label').textContent=(q.options||agreement)[i];label.querySelector('input').checked=answers[index]===i});
 $('#previous').disabled=index===0;
 $('#next-label').textContent=index===questions.length-1?'See results':'Next';
 const status=$('#save-status');status.classList.toggle('sr-only',storageAvailable);status.textContent=storageAvailable?'Progress saved.':'Browser storage is unavailable. Keep this tab open to keep your answers.';
 reserveQuestionSpace();
 $('#question-title').focus({preventScroll:true});
 if(!reuse)window.scrollTo({top:0,behavior:'instant'});
 else {const titleTop=$('#question-title').getBoundingClientRect().top;if(titleTop<0)$('#question-title').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
}
// Measure off-screen once per width, text size and question format. Visible rows keep their positions.
function reserveQuestionSpace(){
 if(view!=='quiz')return;
 const card=$('.question-card'),kind=!!questions[index].options;
 const key=[Math.round(card.getBoundingClientRect().width),db.large,kind,locale].join(':');
 if(key===questionLayoutKey)return;
 questionLayoutKey=key;
 const probe=card.cloneNode(true);
 probe.classList.add('question-measure');
 probe.setAttribute('aria-hidden','true');probe.inert=true;
 probe.style.cssText=`position:fixed;left:-20000px;top:0;width:${card.getBoundingClientRect().width}px;visibility:hidden;pointer-events:none;animation:none;--prompt-height:0px;--answer-height:0px;`;
 probe.querySelector('.question-help').textContent=t('Select to move on, or use the arrows.');
 probe.querySelectorAll('[id]').forEach(node=>node.removeAttribute('id'));
 probe.querySelectorAll('input').forEach(node=>{node.name='measure-response';node.checked=false});
 card.parentElement.append(probe);
 let promptHeight=0,answerHeight=0;
 for(const q of questions.filter(item=>!!item.options===kind)){
  probe.querySelector('h1').textContent=q.text;
  probe.querySelector('.scene').hidden=!q.scene;
  probe.querySelector('.scene p').textContent=q.scene||'';
  promptHeight=Math.max(promptHeight,probe.querySelector('.question-prompt').getBoundingClientRect().height);
  probe.querySelectorAll('.answer-label').forEach((label,i)=>{label.textContent=(q.options||agreement)[i]});
  probe.querySelectorAll('.answer').forEach(label=>{answerHeight=Math.max(answerHeight,label.getBoundingClientRect().height)});
 }
 probe.remove();
 card.style.setProperty('--prompt-height',`${Math.ceil(promptHeight)}px`);
 card.style.setProperty('--answer-height',`${Math.ceil(answerHeight)}px`);
}
function jumpToQuestion(destination){cancelAdvance();if(!Number.isInteger(destination)||destination<0||destination>=questions.length)return;index=destination;persistDraft();quiz()}
function moveQuestion(direction){jumpToQuestion(index+direction)}
function updateQuizShortcuts(){const status=assessmentStatus(answers);$('#answered-count').textContent=`(${status.answered}/45)`;$('#ready-results').hidden=!status.complete;$('#jump-last').hidden=status.complete;$('#jump-last').disabled=index===questions.length-1;updateCompanion();}
const gentleMotionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
function mountJourney(){const companion=$('#growth-companion'),art=$('#growth-art');companion.classList.add('has-journey');companion.querySelector('.companion-copy p:last-child').id='journey-caption';companion.querySelector('.companion-heading').id='journey-heading';companion.insertAdjacentHTML('beforeend',journeyTrailMarkup());$('#journey-traveler').append(art);companion.querySelectorAll('[data-journey-stop]').forEach(button=>button.onclick=()=>{cancelAdvance();const state=journeyState(answers),stop=state.stops[Number(button.dataset.journeyStop)];if(!stop?.available)return;if(stop.index===4&&assessmentStatus(answers).complete)finish();else jumpToQuestion(stop.question)})}
function updateJourney(){const companion=$('#growth-companion');if(!companion?.classList.contains('has-journey'))return;const state=journeyState(answers);companion.style.setProperty('--journey-progress',String(state.progress));companion.style.setProperty('--journey-x',`${state.x}%`);companion.style.setProperty('--journey-y',`${state.y}px`);$('#journey-heading').textContent=`Your journey · ${state.stops[state.activeIndex].name}`;$('#journey-caption').textContent=state.stops[state.activeIndex].caption;companion.querySelectorAll('[data-journey-stop]').forEach(button=>{const stop=state.stops[Number(button.dataset.journeyStop)];button.disabled=!stop.available;button.classList.toggle('current',stop.current);button.classList.toggle('passed',stop.passed);button.setAttribute('aria-label',`${stop.name}, ${stop.current?'current chapter':stop.available?'revisit this chapter':'ahead on your journey'}`);if(stop.current)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');button.title=stop.available?(stop.index===4?'Open your results':`Go to question ${stop.question+1}`):`Opens after ${stop.threshold} answers`;button.querySelector('.journey-pin').textContent=stop.passed?'✓':String(stop.index+1)})}
function updateCompanion(){const companion=$('#growth-companion');if(!companion)return;const state=growthState(answers),paused=db.motionPaused===true||gentleMotionPreference.matches;companion.dataset.growthStage=state.stage;companion.style.setProperty('--stem-reveal',String(state.stem));companion.classList.toggle('motion-paused',paused);$('#growth-art').setAttribute('aria-label',`Progress plant: ${state.name}. ${state.answered} of 45 questions answered.`);const button=$('#motion-toggle');button.disabled=gentleMotionPreference.matches;button.setAttribute('aria-pressed',String(paused));const label=gentleMotionPreference.matches?'Motion paused for your reduced-motion preference':paused?'Resume gentle motion':'Pause gentle motion';button.setAttribute('aria-label',label);button.title=label;button.textContent=paused?'▶':'Ⅱ';updateJourney()}
gentleMotionPreference.addEventListener('change',()=>{if(view==='quiz')updateCompanion()});
function openQuestionPicker(){cancelAdvance();const status=assessmentStatus(answers);showDialog('Jump to a question',`<p>${status.answered} of 45 answered. Your answers stay saved.</p><p class="question-key">✓ Answered &nbsp; · &nbsp; Unmarked questions still need an answer.</p><div class="question-grid">${questions.map((_,i)=>{const answered=Number.isInteger(answers[i])&&answers[i]>=0&&answers[i]<=4;return `<button class="question-number ${answered?'answered':''} ${i===index?'current':''}" data-jump-question="${i}" aria-label="Question ${i+1}, ${answered?'answered':'unanswered'}${i===index?', current question':''}" ${i===index?'aria-current="step"':''}>${i+1}${answered?'<span aria-hidden="true">✓</span>':''}</button>`}).join('')}</div>${status.complete?'<button class="primary picker-results" id="picker-results">Go to results →</button>':''}`);$('#info').querySelectorAll('[data-jump-question]').forEach(button=>button.onclick=()=>{$('#info').close();jumpToQuestion(Number(button.dataset.jumpQuestion))});const results=$('#picker-results');if(results)results.onclick=()=>{$('#info').close();finish()}}
function selectAnswer(value,automatic=true){cancelAdvance();if(view!=='quiz'||!Number.isInteger(value)||value<0||value>4)return;answers[index]=value;persistDraft();const input=app.querySelector(`input[name="response"][value="${value}"]`);if(input&&!input.checked)input.checked=true;const status=$('#save-status');status.classList.toggle('sr-only',storageAvailable);status.textContent=storageAvailable?'Progress saved.':'Browser storage is unavailable. Keep this tab open to keep your answers.';const n=answers.filter(a=>a!==null).length;$('.progress-track').setAttribute('aria-valuenow',n);$('.progress-track>div').style.width=`${n/45*100}%`;updateQuizShortcuts();if(automatic){const answeredIndex=index;advanceTimer=setTimeout(()=>{advanceTimer=null;if(view!=='quiz'||index!==answeredIndex||$('#info').open)return;if(assessmentStatus(answers).complete||index===questions.length-1)finish();else moveQuestion(1)},350)}}
function finish(){cancelAdvance();const unanswered=answers.map((answer,i)=>answer===null?i:-1).filter(i=>i>=0);if(unanswered.length){showDialog('A few answers are still missing.',`<p>${unanswered.length} of 45 questions ${unanswered.length===1?'still needs':'still need'} an answer before we can create your report.</p><div class="dialog-actions"><button class="primary" id="answer-remaining">Answer remaining questions →</button><button class="secondary" data-dialog-close>Keep reviewing</button></div>`);$('#answer-remaining').onclick=()=>{$('#info').close();index=unanswered[0];persistDraft();quiz()};return}prepareReport()}
const nextFrame=()=>new Promise(resolve=>requestAnimationFrame(resolve));
async function prepareReport(){
 setView('preparing');app.innerHTML=preparationMarkup();focusTitle();
 // Yield for the preparation screen to paint; each step reflects actual work, with no countdown.
 await nextFrame();await nextFrame();if(view!=='preparing')return;
 try{const scores=scoreAnswers(answers);$('#prepare-scores').classList.add('complete');
 await nextFrame();if(view!=='preparing')return;
 leanGroups(scores);scores.forEach((_,i)=>categoryInsight(scores,i));$('#prepare-graphs').classList.add('complete');
 const r={version:VERSION,id:crypto.randomUUID(),date:new Date().toISOString(),scores,fullViewed:false,steps:{}};
 db.reports.unshift(r);db.draft=null;currentReport=r;const saved=save();$('#prepare-save').classList.toggle('complete',saved);
 $('#prepare-status').textContent=t(saved?'Your report is ready.':'Report ready. Browser storage is unavailable; save a PDF before leaving.');
 const button=$('#preparation-continue');button.disabled=false;button.onclick=()=>saveReportScreen(r);
 }catch(error){toast(error.message);quiz()}
}
function saveReportScreen(r){if(!r)return;setView('save-report');currentReport=r;app.innerHTML=`<section class="save-report flow-page"><div class="save-flower" aria-hidden="true">✳</div><h1>Keep your discovery close.</h1><p>Your report is saved in this browser. You can also open an email draft with your summary.</p><form id="email-summary"><label for="report-email">Your email address</label><input type="email" id="report-email" name="email" autocomplete="email" placeholder="you@example.com" required><button class="primary" type="submit">Open email draft →</button><p class="support-note">This opens your email app. Review and send the message there. Innerly does not send or collect your email.</p></form><p id="email-status" role="status"></p><button class="text-button" id="skip-save">Skip for now →</button></section>`;
 $('#skip-save').onclick=()=>result(r);$('#email-summary').onsubmit=e=>{e.preventDefault();const email=$('#report-email').value.trim();if(!$('#email-summary').reportValidity())return;const href=emailDraft({email,profile:profileFor(r.scores),scores:r.scores,traits,language:locale,url:location.origin+location.pathname});const link=document.createElement('a');link.href=href;link.click();$('#email-status').textContent=t('Return here to view your report.');$('#skip-save').textContent=t('View my report →')};focusTitle();
 if(!storageAvailable)app.querySelector('.save-report>p').textContent=t('Browser storage is unavailable. Keep this tab open to keep your answers.');
}
const dateLabel=date=>new Date(date).toLocaleDateString(locale==='hi'?'hi-IN':'en-IN',{day:'numeric',month:'long',year:'numeric'});
function graphMarkup(scores){return `<div class="trait-graphs">${traits.map((t,i)=>`<div class="trait-graph"><div class="trait-label"><h3>${t.name}</h3><strong>${scores[i]}<span> / 100</span></strong></div><div class="spectrum" style="--trait-color:${t.color};--position:${scores[i]}%" role="img" aria-label="${t.name}: ${scores[i]} out of 100. Lower scores lean toward ${t.low.toLowerCase()}, higher scores toward ${t.high.toLowerCase()}."><div class="spectrum-fill"></div><span class="spectrum-mid" aria-hidden="true"></span><span class="spectrum-dot" aria-hidden="true"></span></div><div class="spectrum-labels"><span>${t.low}</span><span>${t.high}</span></div></div>`).join('')}</div>`}
function result(r,focus=true){setView('result');currentReport=r;selectedCategory=0;if(!Array.isArray(r.categoryPlan)&&r.steps){const mapping=[0,2,3];r.categoryPlan=mapping.filter((_,i)=>r.steps[i]===true);r.categoryDone=Object.fromEntries(r.categoryPlan.map(i=>[i,true]));save()}const profile=profileFor(r.scores),expanded=r.fullViewed===true;app.innerHTML=`<section class="report-heading"><h1>Your personality</h1><p>${dateLabel(r.date)} · Based on your 45 answers</p></section><section class="summary-card"><div><h2>${profile.title}</h2><p>${profile.summary}</p></div></section><section class="report-panel"><div class="section-heading"><h2>Your five dimensions</h2></div>${graphMarkup(r.scores)}<p class="graph-note">Preferences, not grades. Neither end is better.</p></section><section class="full-report-invite ${expanded?'expanded-invite':''}"><div><h2>Want to understand more?</h2><div class="free-label">Full report · Free for now</div><ul class="report-value-list"><li>Five dimensions, explained simply</li><li>Interactive maps and charts</li><li>Small steps for everyday life</li></ul><p class="support-note">No payment needed. Your full report is free for now.</p></div><button class="primary" data-action="full" aria-expanded="${expanded}" aria-controls="full-report">${expanded?'Go to full report':'View full report'} <span aria-hidden="true">→</span></button></section><section id="full-report" ${expanded?'':'hidden'}>${expanded?fullReportMarkup(r):''}</section><section class="report-panel today-preview"><h2>A small step for today</h2><p>${categoryInsight(r.scores,0).step}</p></section><div class="report-actions"><button class="secondary" data-action="email">Save or email summary</button><button class="secondary" data-action="share">Download summary card</button><button class="secondary" data-action="history">My saved reports</button><button class="text-button" data-action="home">Back to home</button></div><p class="honest-note">For self-reflection. This questionnaire has not been clinically validated.</p>`;bindActions();bindReport();if(focus)focusTitle()}
function profileMapMarkup(r){
 const cx=180,cy=163,radius=101;
 const point=(i,f)=>[cx+Math.cos(-Math.PI/2+i*Math.PI*2/5)*radius*f,cy+Math.sin(-Math.PI/2+i*Math.PI*2/5)*radius*f];
 const polygon=f=>traits.map((_,i)=>point(i,f).join(',')).join(' ');
 return `<svg class="interactive-radar" viewBox="0 0 360 325" role="group" aria-label="Interactive personality map. Select a category point to explore it.">${[.25,.5,.75,1].map(f=>`<polygon points="${polygon(f)}" fill="none" stroke="#d4decb"/>`).join('')}${traits.map((_,i)=>`<line x1="${cx}" y1="${cy}" x2="${point(i,1)[0]}" y2="${point(i,1)[1]}" stroke="#d4decb"/>`).join('')}<polygon points="${r.scores.map((score,i)=>point(i,score/100).join(',')).join(' ')}" fill="#8ca87344" stroke="#6a8855" stroke-width="2"/>${traits.map((t,i)=>{const p=point(i,r.scores[i]/100),label=point(i,1.28);return `<g class="radar-axis ${i===selectedCategory?'active':''}" data-radar-axis="${i}"><line x1="${cx}" y1="${cy}" x2="${point(i,1)[0]}" y2="${point(i,1)[1]}" stroke="${t.color}" class="axis-highlight"/><a href="#category-details" data-category="${i}" aria-label="Explore ${t.name}, ${r.scores[i]} out of 100"><circle cx="${p[0]}" cy="${p[1]}" r="22" fill="transparent"/><circle cx="${p[0]}" cy="${p[1]}" r="5.5" fill="${t.color}" stroke="white" stroke-width="2"/></a><text data-category="${i}" aria-hidden="true" x="${label[0]}" y="${label[1]}" text-anchor="middle" dominant-baseline="middle" fill="#40523a" font-size="16" font-family="Arial, sans-serif">${t.short}</text></g>`}).join('')}</svg>`;
}
function categoryGraphsMarkup(r){return traits.map((t,i)=>`<button class="category-graph ${i===selectedCategory?'active':''}" data-category="${i}" aria-pressed="${i===selectedCategory}" aria-label="Explore ${t.name}, ${r.scores[i]} out of 100"><span class="category-graph-heading"><strong>${t.name}</strong><span>${r.scores[i]} / 100</span></span><span class="mini-spectrum" style="--trait-color:${t.color};--position:${r.scores[i]}%"><span class="mini-fill"></span><span class="mini-mid"></span><span class="mini-dot"></span></span><span class="spectrum-labels"><span>${t.low}</span><span>${t.high}</span></span></button>`).join('')}
function categoryDetailMarkup(r){const insight=categoryInsight(r.scores,selectedCategory),added=selectedActions(r).some(a=>a.index===selectedCategory);return `<div class="category-detail-heading"><div><div class="eyebrow">${insight.trait.name}</div><h3>${insight.title}</h3></div><strong class="category-score" style="--category-color:${insight.trait.color}">${insight.score}<span>/ 100</span></strong></div><div class="simple-insights"><div><h4>What it means</h4><p>${insight.meaning}</p></div><div><h4>Your strength</h4><p>${insight.strength}</p></div><div class="category-suggestion"><h4>Try today</h4><p>${insight.step}</p><button class="${added?'secondary':'primary'}" id="add-category-action" ${added?'disabled':''}>${added?'Added to your plan ✓':'Add to my plan +'}</button></div></div><details class="watch-detail"><summary>One thing to watch for</summary><p>${insight.watch}</p></details>`}
function planMarkup(r){const actions=selectedActions(r),progress=planProgress(r);return `<div class="plan-progress-row"><div class="plan-donut" style="--plan-percent:${progress.percent}%" role="img" aria-label="${progress.done} of ${progress.total} selected activities tried"><span><strong>${progress.done}<small> / ${progress.total}</small></strong><span>steps tried</span></span></div><div><h3>Small steps, your way.</h3><p>${progress.total?'Try an activity, then tick it here. No streaks or deadlines.':'Choose a category above and add one small activity to begin.'}</p><p class="support-note">This chart tracks activities you mark as tried, not personality improvement.</p></div></div><div class="category-action-list">${actions.map(action=>`<div class="saved-category-action"><label><input type="checkbox" data-category-done="${action.index}" ${action.done?'checked':''}><span><strong>${action.trait.name}</strong><span>${action.step}</span></span></label><button class="remove-action" data-remove-category="${action.index}" aria-label="Remove ${action.trait.name.toLowerCase()} activity from my plan">Remove</button></div>`).join('')}</div><div class="plan-live sr-only" role="status">${progress.done} of ${progress.total} steps tried.</div>`}
function barChartMarkup(r){return `<p class="support-note">Each bar is a separate 0–100 preference score. Tap a bar for its suggestion.</p><div class="vertical-bar-chart" aria-label="Personality category bar chart"><div class="bar-scale" aria-hidden="true"><span>100</span><span>50</span><span>0</span></div><div class="vertical-bars">${traits.map((t,i)=>`<button class="score-column ${i===selectedCategory?'active':''}" data-category="${i}" aria-pressed="${i===selectedCategory}" aria-label="Explore ${t.name}, ${r.scores[i]} out of 100"><span class="column-area"><span class="column-fill" style="--column-height:${r.scores[i]}%;--column-color:${t.color}"></span><strong class="column-value" style="--column-height:${r.scores[i]}%">${r.scores[i]}</strong></span><span class="column-label"><span class="column-short">${t.short}</span><span class="column-index">${i+1}</span></span></button>`).join('')}</div></div><div class="bar-mobile-legend">${traits.map((t,i)=>`<button data-category="${i}" aria-pressed="${i===selectedCategory}"><span>${i+1}</span>${t.name}</button>`).join('')}</div>`}
function pieChartMarkup(r){const groups=leanGroups(r.scores),active=band(r.scores[selectedCategory]);return `<p class="support-note">How your five categories group by preference. These slices count categories, not parts of your personality.</p><div class="pie-layout"><svg class="preference-pie" viewBox="0 0 280 280" role="group" aria-label="Preference grouping pie chart">${groups.filter(g=>g.count>0).map(group=>{const i=groups.indexOf(group);return `<a href="#pie-categories" data-lean="${i}" aria-label="${group.label}: ${group.count} of 5 categories, ${group.percent} percent"><path d="${wedgePath(group.start,group.end)}" fill="${group.color}" stroke="white" stroke-width="3" class="pie-slice ${i===active?'active':''}" data-pie-slice="${i}"/><title>${group.label}: ${group.count} of 5 (${group.percent}%)</title></a>`}).join('')}</svg><div class="pie-legend">${groups.map((group,i)=>`<button data-lean="${i}" aria-pressed="${i===active}" ${group.count===0?'disabled':''}><span class="legend-swatch" style="background:${group.color}"></span><span>${group.label}<small>${group.count} of 5 · ${group.percent}%</small></span></button>`).join('')}</div></div><div id="pie-categories" class="pie-category-list">${pieCategoryMarkup(r,active)}</div>`}
function pieCategoryMarkup(r,groupIndex){const group=leanGroups(r.scores)[groupIndex];return `<p><strong>${group.label}</strong> — ${group.count} ${group.count===1?'category':'categories'}</p><div class="pie-category-buttons">${group.indices.map(i=>`<button data-category="${i}" aria-pressed="${i===selectedCategory}">${traits[i].name} · ${r.scores[i]}</button>`).join('')}</div>`}
function lineChartMarkup(r){const series=historySeries(db.reports,r,selectedCategory),width=600,left=47,right=568,top=30,bottom=228,x=i=>series.length===1?(left+right)/2:left+i*(right-left)/(series.length-1),y=score=>bottom-score/100*(bottom-top),latest=series[series.length-1];return `<div class="history-category-control"><label for="history-category">Choose category</label><select id="history-category">${traits.map((t,i)=>`<option value="${i}" ${i===selectedCategory?'selected':''}>${t.name}</option>`).join('')}</select></div><p class="support-note">${series.length===1?'Your first saved score is shown as one point. A line appears after another completed assessment.':'Your latest '+series.length+' saved assessments, oldest to newest. A change is not automatically an improvement.'}</p><svg class="history-line" viewBox="0 0 ${width} 278" role="group" aria-label="${traits[selectedCategory].name} scores across ${series.length} saved assessments">${[0,50,100].map(score=>`<line x1="${left}" y1="${y(score)}" x2="${right}" y2="${y(score)}" stroke="#dae3d0" stroke-dasharray="${score===50?'5 5':'0'}"/><text x="${left-10}" y="${y(score)+5}" text-anchor="end" fill="#53654a" font-size="16">${score}</text>`).join('')}${series.length>1?`<polyline points="${series.map((point,i)=>`${x(i)},${y(point.score)}`).join(' ')}" fill="none" stroke="${traits[selectedCategory].color}" stroke-width="3"/>`:''}${series.map((point,i)=>`<a href="#history-point-detail" data-history-point="${i}" aria-label="${dateLabel(point.date)}: ${point.score} out of 100"><circle cx="${x(i)}" cy="${y(point.score)}" r="20" fill="transparent"/><circle cx="${x(i)}" cy="${y(point.score)}" r="6" fill="${traits[selectedCategory].color}" stroke="white" stroke-width="2"/><title>${dateLabel(point.date)}: ${point.score} / 100</title></a><text x="${x(i)}" y="${bottom+32}" text-anchor="middle" fill="#53654a" font-size="15">${i+1}</text>`).join('')}<text x="${(left+right)/2}" y="273" text-anchor="middle" fill="#53654a" font-size="15">Saved assessments</text></svg><p id="history-point-detail" class="history-point-detail" role="status">${dateLabel(latest.date)} · ${traits[selectedCategory].name}: <strong>${latest.score} / 100</strong></p><details class="history-values"><summary>See exact dates and scores</summary><table><thead><tr><th>Assessment date</th><th>Score</th></tr></thead><tbody>${series.map(point=>`<tr><td>${dateLabel(point.date)}</td><td>${point.score} / 100</td></tr>`).join('')}</tbody></table></details>`}
function chartGalleryMarkup(r){return `<section class="report-panel chart-gallery"><h3>See it another way</h3><div class="chart-tabs" role="tablist" aria-label="Choose a graph type">${[['bar','Bar chart'],['pie','Pie chart'],['line','Line graph']].map(([key,label],i)=>`<button role="tab" id="tab-${key}" data-chart-tab="${key}" aria-selected="${i===0}" aria-controls="panel-${key}" tabindex="${i===0?'0':'-1'}">${label}</button>`).join('')}</div><section id="panel-bar" role="tabpanel" aria-labelledby="tab-bar"><div id="bar-chart-content">${barChartMarkup(r)}</div></section><section id="panel-pie" role="tabpanel" aria-labelledby="tab-pie" hidden><div id="pie-chart-content">${pieChartMarkup(r)}</div></section><section id="panel-line" role="tabpanel" aria-labelledby="tab-line" hidden><div id="line-chart-content">${lineChartMarkup(r)}</div></section></section>`}
function fullReportMarkup(r){return `<div class="full-report-heading"><h2 tabindex="-1" id="full-report-title">Explore your personality.</h2><p>Tap a graph or category. Find a small step that suits you.</p></div><div class="report-graph-grid"><section class="report-panel"><h3>Your profile map</h3><p class="support-note">Tap a point or use the category buttons below.</p><p class="selected-category-caption" id="chart-selection" role="status">${traits[selectedCategory].name} · ${r.scores[selectedCategory]} / 100</p>${profileMapMarkup(r)}<p class="graph-note">A larger shape is not a better personality.</p></section><section class="report-panel"><h3>Your preference balance</h3><p class="support-note">Tap any row to understand that category.</p><div class="category-graphs">${categoryGraphsMarkup(r)}</div></section></div>${chartGalleryMarkup(r)}<section class="report-panel category-explorer"><h3>What can I try?</h3><div class="category-buttons" role="group" aria-label="Choose a personality category">${traits.map((t,i)=>`<button class="category-select ${i===selectedCategory?'active':''}" data-category="${i}" aria-pressed="${i===selectedCategory}">${t.name}</button>`).join('')}</div><div id="category-details" aria-live="polite" aria-atomic="true">${categoryDetailMarkup(r)}</div></section><section class="report-panel category-plan" aria-labelledby="plan-title"><h2 id="plan-title">My simple action plan</h2><div id="category-plan-content">${planMarkup(r)}</div></section><details class="report-panel all-category-details"><summary>See all five categories together</summary><div class="all-category-content">${traits.map((t,i)=>{const item=categoryInsight(r.scores,i);return `<article><h3>${t.name} · ${r.scores[i]} / 100</h3><p>${item.meaning}</p><h4>Try today</h4><p>${item.step}</p></article>`}).join('')}</div></details><details class="report-panel methodology"><summary>How your scores work</summary><p>Each category uses nine equally weighted answers, scored from 0 to 4. Opposite-worded items are reversed. Each total is divided by 36 and shown from 0 to 100.</p><p>Below 40 leans left, 40–60 suggests a mix, and above 60 leans right. These are illustrative bands, not validated cutoffs. Scores are preferences, not grades or population percentiles.</p><p>This original self-reflection questionnaire has not been clinically validated.</p></details><div class="print-action"><button class="primary" data-action="print">Save full report as PDF ↓</button><p class="support-note">Choose “Save as PDF” in your browser’s print window.</p></div>`}
function openFullReport(){if(!currentReport)return;const container=$('#full-report');if(!currentReport.fullViewed){currentReport.fullViewed=true;save();container.innerHTML=fullReportMarkup(currentReport);container.hidden=false;const button=app.querySelector('[data-action="full"]');button.setAttribute('aria-expanded','true');button.textContent='Go to full report →';bindReport();container.querySelector('[data-action="print"]').onclick=()=>window.print()}$('#full-report-title').focus({preventScroll:true});container.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function bindReport(){if(!currentReport||!$('#full-report')||$('#full-report').hidden)return;
 app.querySelectorAll('[data-category]').forEach(button=>button.onclick=e=>{e.preventDefault();chooseCategory(Number(button.dataset.category))});
 bindCategoryAction();bindCategoryPlan();bindChartGallery();
}
function chooseCategory(index){if(!Number.isInteger(index)||index<0||index>=traits.length)return;selectedCategory=index;
 app.querySelectorAll('[data-category]').forEach(button=>{const active=Number(button.dataset.category)===index;button.classList.toggle('active',active);if(button.tagName.toLowerCase()==='button')button.setAttribute('aria-pressed',String(active))});
 app.querySelectorAll('[data-radar-axis]').forEach(axis=>axis.classList.toggle('active',Number(axis.dataset.radarAxis)===index));
 $('#category-details').innerHTML=categoryDetailMarkup(currentReport);$('#chart-selection').textContent=`${traits[index].name} · ${currentReport.scores[index]} / 100`;bindCategoryAction();syncGalleryCategory();
}
function selectChartTab(key,focus=false){for(const tab of app.querySelectorAll('[data-chart-tab]')){const active=tab.dataset.chartTab===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$('#panel-'+tab.dataset.chartTab).hidden=!active;if(active&&focus)tab.focus()}}
function bindChartGallery(){app.querySelectorAll('[data-chart-tab]').forEach(tab=>{tab.onclick=()=>selectChartTab(tab.dataset.chartTab);tab.onkeydown=e=>{const keys=['bar','pie','line'],index=keys.indexOf(tab.dataset.chartTab);let next;if(e.key==='ArrowRight')next=(index+1)%3;if(e.key==='ArrowLeft')next=(index+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next!==undefined){e.preventDefault();selectChartTab(keys[next],true)}}});bindPieControls();bindLineControls()}
function bindGalleryCategories(){app.querySelectorAll('#panel-bar [data-category],#panel-pie [data-category]').forEach(button=>button.onclick=e=>{e.preventDefault();chooseCategory(Number(button.dataset.category))})}
function bindPieControls(){app.querySelectorAll('[data-lean]').forEach(button=>button.onclick=e=>{e.preventDefault();const group=Number(button.dataset.lean),groups=leanGroups(currentReport.scores);if(!groups[group]?.count)return;app.querySelectorAll('[data-lean]').forEach(item=>{if(item.tagName.toLowerCase()==='button')item.setAttribute('aria-pressed',String(Number(item.dataset.lean)===group))});app.querySelectorAll('[data-pie-slice]').forEach(slice=>slice.classList.toggle('active',Number(slice.dataset.pieSlice)===group));$('#pie-categories').innerHTML=pieCategoryMarkup(currentReport,group);bindGalleryCategories()})}
function bindLineControls(){const select=$('#history-category');if(select)select.onchange=()=>chooseCategory(Number(select.value));app.querySelectorAll('[data-history-point]').forEach(point=>point.onclick=e=>{e.preventDefault();const series=historySeries(db.reports,currentReport,selectedCategory),item=series[Number(point.dataset.historyPoint)];if(item){$('#history-point-detail').textContent=`${dateLabel(item.date)} · ${traits[selectedCategory].name}: ${item.score} / 100`;app.querySelectorAll('[data-history-point]').forEach(other=>other.classList.toggle('active',other===point))}})}
function syncGalleryCategory(){if(!$('#bar-chart-content'))return;const historyFocused=document.activeElement?.id==='history-category';$('#pie-chart-content').innerHTML=pieChartMarkup(currentReport);$('#line-chart-content').innerHTML=lineChartMarkup(currentReport);bindGalleryCategories();bindPieControls();bindLineControls();if(historyFocused)$('#history-category').focus({preventScroll:true})}
function bindCategoryAction(){const button=$('#add-category-action');if(!button)return;button.onclick=()=>{const existing=selectedActions(currentReport).map(a=>a.index);currentReport.categoryPlan=[...new Set([...existing,selectedCategory])];save();button.disabled=true;button.className='secondary';button.textContent='Added to your plan ✓';updateCategoryPlan();toast('Added to your plan. Try it whenever you like.')}}
function updateCategoryPlan(){$('#category-plan-content').innerHTML=planMarkup(currentReport);bindCategoryPlan()}
function bindCategoryPlan(){app.querySelectorAll('[data-category-done]').forEach(input=>input.onchange=()=>{const index=Number(input.dataset.categoryDone);currentReport.categoryDone=currentReport.categoryDone||{};currentReport.categoryDone[index]=input.checked;save();const progress=planProgress(currentReport),donut=$('.plan-donut');donut.style.setProperty('--plan-percent',`${progress.percent}%`);donut.setAttribute('aria-label',`${progress.done} of ${progress.total} selected activities tried`);donut.querySelector('strong').innerHTML=`${progress.done}<small> / ${progress.total}</small>`;$('.plan-live').textContent=`${progress.done} of ${progress.total} steps tried.`});app.querySelectorAll('[data-remove-category]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.removeCategory);currentReport.categoryPlan=selectedActions(currentReport).filter(a=>a.index!==index).map(a=>a.index);if(currentReport.categoryDone)delete currentReport.categoryDone[index];save();updateCategoryPlan();if(selectedCategory===index){$('#category-details').innerHTML=categoryDetailMarkup(currentReport);bindCategoryAction()}})}
function legacyReports(){try{const old=JSON.parse(localStorage.getItem('innerly-v1'));return Array.isArray(old?.reports)?old.reports.filter(r=>['patterns','communication','emotions'].includes(r.test)&&typeof r.id==='string'&&/^\d+$/.test(r.id)&&Array.isArray(r.dims)&&r.dims.length===3&&r.dims.every(s=>Number.isFinite(s)&&s>=0&&s<=100)&&!Number.isNaN(Date.parse(r.date))):[]}catch{return []}}
function history(){setView('history');const legacy=legacyReports();app.innerHTML=`<section class="report-heading"><div class="eyebrow">YOUR PERSONAL SPACE</div><h1>Your saved reports.</h1><p>Saved on this browser. Return whenever you like.</p></section>${db.reports.length?db.reports.map(r=>`<article class="history-card"><div><span class="eyebrow">45-QUESTION PERSONALITY REFLECTION</span><h2>${profileFor(r.scores).title}</h2><p>${dateLabel(r.date)}</p></div><button class="secondary" data-report="${escape(r.id)}">View report <span aria-hidden="true">→</span></button></article>`).join(''):`<section class="empty-state"><span aria-hidden="true">♧</span><h2>Your first discovery is waiting.</h2><p>Complete the assessment to see your personality graphs and report here.</p><button class="primary" data-action="${db.draft?'resume':'start'}">${db.draft?'Continue assessment':'Start assessment'} →</button></section>`}${legacy.length?`<section class="legacy-section"><h2>Your earlier reflections</h2><p>These are from the previous short assessments and use a different scoring method.</p>${legacy.map(r=>`<article class="history-card"><div><h3>${({patterns:'Your inner pattern',communication:'Your communication',emotions:'Your emotional world'})[r.test]}</h3><p>${dateLabel(r.date)}</p></div><button class="secondary" data-legacy="${escape(r.id)}">View reflection</button></article>`).join('')}</section>`:''}`;bindActions();app.querySelectorAll('[data-legacy]').forEach(b=>b.onclick=()=>{const r=legacy.find(r=>r.id===b.dataset.legacy),names=({patterns:['Self-awareness','Flexibility','Intentional action'],communication:['Direct expression','Perspective-taking','Healthy boundaries'],emotions:['Emotional awareness','Self-compassion','Regulation']})[r.test];showDialog('Your earlier reflection',`<p>${dateLabel(r.date)} · Previous 12-question exercise</p>${names.map((n,i)=>`<p><strong>${n}:</strong> ${r.dims[i]} / 100</p>`).join('')}<p>This original exercise was not clinically validated. Its scores are not comparable with the new personality assessment.</p><button class="secondary" data-dialog-close>Close reflection</button>`)});focusTitle()}
function shareReport(){if(!currentReport)return;const r=currentReport,p=profileFor(r.scores);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1200"><rect width="1080" height="1200" fill="#f1f5e9"/><text x="80" y="115" fill="#294e3c" font-family="Georgia" font-size="48">✳ innerly.</text><text x="80" y="230" fill="#294e3c" font-family="Georgia" font-size="${Math.min(44,Math.floor(1350/t(p.title).length))}">${escape(t(p.title))}</text><text x="80" y="295" fill="#56684c" font-family="Arial, sans-serif" font-size="25">${locale==='hi'?'मेरी व्यक्तित्व झलक · 45 सवाल':'My personality snapshot · 45-question reflection'}</text>${traits.map((t,i)=>`<text x="80" y="${410+i*125}" fill="#294e3c" font-family="Arial, sans-serif" font-size="29">${t.name}</text><text x="980" y="${410+i*125}" text-anchor="end" fill="#294e3c" font-family="Arial, sans-serif" font-size="29">${r.scores[i]} / 100</text><rect x="80" y="${435+i*125}" width="900" height="14" rx="7" fill="#dce5d0"/><rect x="80" y="${435+i*125}" width="${r.scores[i]*9}" height="14" rx="7" fill="${t.color}"/>`).join('')}<text x="80" y="1100" fill="#56684c" font-family="Arial, sans-serif" font-size="23">${locale==='hi'?'ये पसंद हैं, अंक नहीं। खुद को समझने की शुरुआत।':'Preferences, not grades. A starting point, not a label.'}</text><text x="80" y="1150" fill="#56684c" font-family="Arial, sans-serif" font-size="20">${locale==='hi'?'मौलिक आत्म-चिंतन अभ्यास · क्लिनिकल सत्यापन नहीं हुआ':'Original self-reflection exercise · Not clinically validated'}</text></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='my-innerly-personality.svg';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your summary card is downloaded. Share it only if you want to.')}
function showDialog(title,content){cancelAdvance();$('#info').innerHTML=`<button class="close-dialog" aria-label="Close dialog">×</button><h2 id="dialog-title">${title}</h2>${content}`;$('#info').querySelectorAll('[data-dialog-close],.close-dialog').forEach(b=>b.onclick=()=>$('#info').close());$('#info').showModal()}
function about(){showDialog('A mirror, not a label.',`<p>Innerly is a name inspired by your inner world: your thoughts, feelings, and preferences.</p><p>This is an original, unvalidated self-reflection questionnaire. It does not diagnose a condition or measure your worth, abilities, or suitability.</p><p>Assessment answers, unfinished progress, reports, language, motion and text-size preferences are stored in this browser. No account is needed. There is no server collection of your responses. Downloading a card does not post it anywhere. The optional email draft opens your own email app; you decide whether to send it.</p><p>Your short summary and full report are free for now. No payment details are collected.</p><button class="secondary" id="clear-data">Clear my saved data</button>`);$('#clear-data').onclick=()=>{showDialog('Clear data on this device?',`<p>This removes your unfinished answers, completed reports, and earlier reflections from this browser. Download any report you want to keep first.</p><div class="dialog-actions"><button class="secondary" data-dialog-close>Keep my data</button><button class="danger" id="confirm-clear">Clear my data</button></div>`);$('#confirm-clear').onclick=()=>{try{localStorage.removeItem(storageKey);localStorage.removeItem('innerly-v1');db={reports:[],draft:null,large:db.large};save();$('#info').close();currentReport=null;home();toast('Your saved answers and reports have been cleared.')}catch{toast('This browser could not clear saved data. Please use your browser’s storage settings.')}}}}
function goHome(){if(view==='quiz')persistDraft();home()}
$('#home-nav').onclick=goHome;$('.brand').onclick=e=>{e.preventDefault();goHome()};$('#reports-nav').onclick=()=>{if(view==='quiz')persistDraft();history()};$('#regular-type').onclick=()=>setText(false);$('#large-type').onclick=()=>setText(true);$('#about').onclick=$('#privacy').onclick=about;$('#info').addEventListener('click',e=>{if(e.target===$('#info'))$('#info').close()});document.addEventListener('keydown',e=>{if(view!=='quiz'||$('#info').open||e.ctrlKey||e.metaKey||e.altKey||e.repeat||!/^Digit[1-5]$/.test(e.code))return;e.preventDefault();const value=Number(e.code.slice(-1))-1;selectAnswer(value);app.querySelector(`input[value="${value}"]`).focus()});window.addEventListener('beforeunload',e=>{if(view==='quiz'&&hasUnsavedAnswers){e.preventDefault();e.returnValue=''}});setText(db.large,false);home(false);
const translatePage=installPageTranslation();
const languageControl=$('#language');languageControl.value=locale;
languageControl.onchange=()=>{cancelAdvance();if(view==='quiz')persistDraft();const chosen=languageControl.value;setLocale(chosen);localizeModel(locale);document.documentElement.lang=locale;document.title=locale==='hi'?'Innerly — खुद को जानें, अपनी गति से':'Innerly — Understand yourself, at your own pace';try{localStorage.setItem('innerly-language',locale)}catch{}const url=new URL(location.href);url.searchParams.set('lang',locale);window.history.replaceState(null,'',url);questionLayoutKey='';if($('#info').open)$('#info').close();if(view==='quiz')quiz();else if(view==='home')home(false);else if(view==='result'){const category=selectedCategory;result(currentReport,false);if(currentReport.fullViewed)chooseCategory(category)}else if(view==='history')history();else if(view==='save-report')saveReportScreen(currentReport);translatePage();};

window.addEventListener('resize',()=>{if(view==='quiz')reserveQuestionSpace()});
document.fonts.ready.then(()=>{if(view==='quiz'){questionLayoutKey='';reserveQuestionSpace()}});

let closedPrintDetails=[],hiddenPrintPanels=[];
window.addEventListener('beforeprint',()=>{hiddenPrintPanels=[...document.querySelectorAll('.chart-gallery [role=tabpanel][hidden]')];hiddenPrintPanels.forEach(panel=>{panel.hidden=false});closedPrintDetails=[...document.querySelectorAll('#full-report details:not([open])')];closedPrintDetails.forEach(detail=>{detail.open=true})});
window.addEventListener('afterprint',()=>{hiddenPrintPanels.forEach(panel=>{if(panel.isConnected)panel.hidden=true});hiddenPrintPanels=[];closedPrintDetails.forEach(detail=>{if(detail.isConnected)detail.open=false});closedPrintDetails=[]});
